import Medusa from '@medusajs/js-sdk';

const medusa = new Medusa({
  baseUrl: process.env.MEDUSA_BACKEND_URL ?? 'http://localhost:9000',
  publishableKey: process.env.NEXT_PUBLIC_MEDUSA_PUBLISHABLE_KEY!,
});

// Fetch the first page of products with their variants and images
const { products, count, offset, limit } = await medusa.store.product.list({
  limit: 20,
  offset: 0,
  fields: '+variants,+images,+thumbnail',
});

console.log(`Found ${count} total products, showing ${products.length}`);

for (const product of products) {
  console.log(`- ${product.title} (${product.variants?.length ?? 0} variants)`);
  const prices = product.variants?.map((v) =>
    v.calculated_price?.calculated_amount
  );
  console.log(`  Price range: ${Math.min(...(prices ?? [0]))} – ${Math.max(...(prices ?? [0]))}`);
}

import Medusa from '@medusajs/js-sdk';

const medusa = new Medusa({
  baseUrl: process.env.MEDUSA_BACKEND_URL ?? 'http://localhost:9000',
  publishableKey: process.env.NEXT_PUBLIC_MEDUSA_PUBLISHABLE_KEY!,
});

// Step 1: Retrieve available regions
const { regions } = await medusa.store.region.list();
const region = regions[0]; // Use the first region (e.g., United States)

// Step 2: Create an empty cart for the region
const { cart } = await medusa.store.cart.create({
  region_id: region.id,
  currency_code: region.currency_code,
});

console.log('Created cart:', cart.id);

// Step 3: Add a line item (requires a valid variant ID from your store)
const variantId = 'variant_01JEXAMPLE'; // Replace with a real variant ID

const { cart: updatedCart } = await medusa.store.cart.createLineItem(cart.id, {
  variant_id: variantId,
  quantity: 1,
});

console.log(
  `Cart now has ${updatedCart.items?.length} item(s)`,
  `Total: ${updatedCart.total} ${updatedCart.currency_code?.toUpperCase()}`
);
